<script setup lang="ts">definePageMeta({layout:'workspace'});const db=useSupabaseClient();const {schoolId,platformAdmin,schoolOptions}=useSchool();const counts=ref({students:0,houses:0,staff:0,competitions:0});const competitions=ref<any[]>([]);const error=ref('');const loading=ref(false);async function load(){if(!schoolId.value)return;loading.value=true;try{const id=schoolId.value;const [s,h,m,c]=await Promise.all([db.from('students').select('id',{count:'exact',head:true}).eq('school_id',id),db.from('school_houses').select('id',{count:'exact',head:true}).eq('school_id',id),db.from('school_memberships').select('user_id',{count:'exact',head:true}).eq('school_id',id),db.from('competitions').select('id,name,status,school_year').eq('organiser_school_id',id).limit(10)]);const failure=[s,h,m,c].find(x=>x.error)?.error;if(failure)throw failure;counts.value={students:s.count||0,houses:h.count||0,staff:m.count||0,competitions:c.data?.length||0};competitions.value=c.data||[]}catch(e:any){error.value=e?.message||'Unable to load dashboard'}finally{loading.value=false}}watch(schoolId,load,{immediate:true})</script><template><div class="space-y-7"><UiPageHeader title="Overview" description="Your school sports workspace"/><p v-if="error" role="alert" class="text-red-600">{{error}}</p><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><UiStatCard title="Students" :value="counts.students"/><UiStatCard title="Houses" :value="counts.houses"/><UiStatCard title="Staff" :value="counts.staff"/><UiStatCard title="Competitions" :value="counts.competitions"/></div><UiPanel><h2 class="mb-4 text-lg font-bold">Recent competitions</h2><p v-if="loading">Loading…</p><div v-else class="divide-y divide-[var(--border)]"><NuxtLink v-for="c in competitions" :key="c.id" :to="{path:'/school/competitions',query:{school:schoolId,competition:c.id}}" class="flex justify-between py-4 text-sm"><span class="font-semibold">{{c.name}}</span><span class="text-[var(--muted)]">{{c.status}}</span></NuxtLink><p v-if="!competitions.length" class="py-4 text-sm text-[var(--muted)]">No competitions yet.</p></div></UiPanel></div></template>